use super::*;
use crate::pet_runtime::{recovery_tests::Environment,authority_tests::root,reconciliation_tests::inventory,model::State as GoalState,store::Fault};
#[test]fn recovery_inputs_accept_only_native_references_and_explicit_choice(){
    let extra=serde_json::json!({"petId":"ai_ollama","goalId":"g","revision":"r","token":"t","approve":true,"ownerAbsent":true,"closure":{"signed":true}});assert!(serde_json::from_value::<RecoveryConfirmInput>(extra).is_err());
    let extra=serde_json::json!({"petId":"ai_ollama","goalId":"g","revision":"r","requestId":"q","budget":{"maxModelCalls":999},"sourceGrantHash":"forged"});assert!(serde_json::from_value::<RecoveryPrepareInput>(extra).is_err());
}
fn input(env:&Environment,request:&str)->RecoveryPrepareInput{RecoveryPrepareInput{pet_id:env.goal.spec.owner.pet_id.clone(),goal_id:env.goal.id.clone(),revision:env.goal.revision.clone(),request_id:request.into()}}
fn choice(ticket:&RecoveryTicket)->RecoveryConfirmInput{RecoveryConfirmInput{pet_id:ticket.proposal.pet_id.clone(),goal_id:ticket.proposal.goal_id.clone(),revision:ticket.proposal.revision.clone(),token:ticket.token.clone(),approve:true}}
#[test]fn native_recovery_ticket_is_window_pet_goal_and_revision_scoped_and_decline_has_no_writes(){
    let env=Environment::new("ollama","started",true);let mut cache=Reviews::default();let before=inventory(&env.fixture.path);let ticket=cache.insert("settings","close".into(),env.review("close"),100_020).unwrap();let same=cache.find("settings",&input(&env,"close"),100_021).unwrap().unwrap();assert_eq!(same.token,ticket.token);let mut c=choice(&ticket);assert!(cache.lookup("pet-control",&c).is_err());c.pet_id="agent_codex".into();assert!(cache.lookup("settings",&c).is_err());c=choice(&ticket);c.revision="0".repeat(32);assert!(cache.lookup("settings",&c).is_err());
    let pending=cache.lookup("settings",&choice(&ticket)).unwrap();assert!(matches!(pending.confirm(&env.store,false,100_022).unwrap(),RecoveryConfirmed::Declined));assert_eq!(inventory(&env.fixture.path),before);drop(pending);cache.sweep(100_023);assert!(cache.pending.is_empty());drop(env.review("after-decline"));
}
#[test]fn approval_survives_busy_and_uncertain_ack_and_reload_returns_the_original_cleanup_ticket(){
    let mut env=Environment::new("ollama","started",true);let mut cache=Reviews::default();let ticket=cache.insert("settings","close".into(),env.review("close"),100_020).unwrap();let pending=cache.lookup("settings",&choice(&ticket)).unwrap();let lock=env.store.test_lock(true).unwrap();let before=inventory(&env.fixture.path);let blocked=pending.confirm(&env.store,true,100_021).unwrap();assert!(matches!(blocked,RecoveryConfirmed::Blocked{reason:Error::Busy,retryable:true,..}));assert_eq!(inventory(&env.fixture.path),before);drop(lock);
    env.store.fault=Fault::AfterPublish;let uncertain=pending.confirm(&env.store,true,100_022).unwrap();let RecoveryConfirmed::Closed{receipt}=uncertain else{panic!("approved closure must publish")};assert_eq!(receipt.status,model::CommitStatus::Uncertain);let mut refreshed=input(&env,"after-ui-reload");refreshed.revision=receipt.record.revision;let cleanup=cache.find("settings",&refreshed,300_000).unwrap().unwrap();assert_eq!(cleanup.token,ticket.token);assert_eq!(cleanup.proposal.approval_scope,"ackRecordedClosure");assert_eq!(cleanup.proposal.revision,ticket.proposal.revision);let grant=env.grant();env.store.fault=Fault::None;
    let RecoveryConfirmed::Closed{receipt}=pending.confirm(&env.store,true,300_001).unwrap()else{panic!("same original ACK required")};assert_eq!(receipt.record.state,GoalState::RecoveryRequired);assert_eq!(env.grant(),grant);assert_eq!(env.grant()["recovery"]["reference"]["approvedAt"],100_021);
}
#[test]fn an_expired_unapproved_ticket_is_released_but_an_uncommitted_choice_can_be_explicitly_withdrawn(){
    let env=Environment::new("ollama","started",true);let mut cache=Reviews::default();let ticket=cache.insert("settings","expiry".into(),env.review("expiry"),100_020).unwrap();let before=inventory(&env.fixture.path);cache.sweep(130_021);assert!(cache.lookup("settings",&choice(&ticket)).is_err());assert_eq!(inventory(&env.fixture.path),before);
    let ticket=cache.insert("settings","choice".into(),env.review("choice"),100_020).unwrap();let pending=cache.lookup("settings",&choice(&ticket)).unwrap();let lock=env.store.test_lock(true).unwrap();assert!(matches!(pending.confirm(&env.store,true,100_021).unwrap(),RecoveryConfirmed::Blocked{reason:Error::Busy,..}));drop(lock);let before=inventory(&env.fixture.path);assert!(matches!(pending.confirm(&env.store,false,100_022).unwrap(),RecoveryConfirmed::Declined));assert_eq!(inventory(&env.fixture.path),before);assert!(env.grant().get("recovery").is_none());assert!(root(&env.fixture).is_dir());
}
